1	/**
2	 * Cloud inference providers: one declaration per provider feeds configuration, credential scoping, disclosure policy
3	 * and request construction. The local appliance is not a provider here: a configuration without a provider id keeps
4	 * the original endpoint path (LOCAL_LLM_*, stored gateway token, X-Task-Class, endpoint failover) unchanged.
5	 *
6	 * Separate concepts:
7	 * - Provider definition (PROVIDERS): identity, wire protocol, default base URL, credential variable, auth style.
8	 * - Connection (ResolvedConnection): the base URL actually used, its credential scope and disclosure class.
9	 * - Model: the provider's model id, passed verbatim (ids may contain "/" and ":").
10	 * - Role binding: main, planner and coder each name their own provider; subagents and auxiliary calls inherit main.
11	 */
12	import { classifyDestination } from "./core/egress.js";
13	
14	export type WireProtocol = "openai-chat" | "openai-responses" | "anthropic-messages";
15	export type AuthStyle = "bearer" | "x-api-key" | "none" | "oauth";
16	
17	/** How an operator can connect a provider from the TUI or `nexus connect`. */
18	export interface ConnectMethod {
19	  id: string;
20	  label: string;
21	  kind: "key" | "browser" | "device";
22	  /** Uses another vendor's client identity; the providers' terms may not permit it. */
23	  unofficial?: boolean;
24	}
25	
26	export interface ProviderDefinition {
27	  id: string;
28	  label: string;
29	  protocol: WireProtocol;
30	  /** Includes the provider's API path and version; nothing is appended except the operation path. */
31	  baseUrl?: string;
32	  /** Environment variable holding this provider's key (none for sign-in-only providers). Sent only to the connection's own origin. */
33	  credentialEnv?: string;
34	  methods: ConnectMethod[];
35	  /** The backend accepts streamed requests only; non-streaming calls are streamed internally. */
36	  streamOnly?: boolean;
37	  /** Request parameters this backend rejects for every model; never sent. */
38	  omitParams?: string[];
39	  auth: AuthStyle;
40	  /** Headers this provider requires on every request. */
41	  staticHeaders?: Record<string, string>;
42	  /** Ask the provider to report usage (and, where offered, cost) on streamed responses. */
43	  usage: "openrouter" | "stream-options" | "native";
44	}
45	
46	export const PROVIDERS: Readonly<Record<string, ProviderDefinition>> = Object.freeze({
47	  openrouter: {
48	    id: "openrouter",
49	    label: "OpenRouter",
50	    protocol: "openai-chat",
51	    baseUrl: "https://openrouter.ai/api/v1",
52	    credentialEnv: "OPENROUTER_API_KEY",
53	    auth: "bearer",
54	    staticHeaders: { "X-Title": "Nexus" },
55	    usage: "openrouter",
56	    methods: [
57	      { id: "api-key", label: "API key", kind: "key" },
58	      { id: "openrouter-oauth", label: "Sign in with OpenRouter", kind: "browser" },
59	    ],
60	  },
61	  openai: {
62	    id: "openai",
63	    label: "OpenAI",
64	    protocol: "openai-responses",
65	    baseUrl: "https://api.openai.com/v1",
66	    credentialEnv: "OPENAI_API_KEY",
67	    auth: "bearer",
68	    usage: "native",
69	    methods: [{ id: "api-key", label: "API key", kind: "key" }],
70	  },
71	  anthropic: {
72	    id: "anthropic",
73	    label: "Anthropic",
74	    protocol: "anthropic-messages",
75	    baseUrl: "https://api.anthropic.com/v1",
76	    credentialEnv: "ANTHROPIC_API_KEY",
77	    auth: "x-api-key",
78	    staticHeaders: { "anthropic-version": "2023-06-01" },
79	    usage: "native",
80	    methods: [{ id: "api-key", label: "API key", kind: "key" }],
81	  },
82	  /** ChatGPT Plus/Pro plan through the Codex backend (unofficial: Codex CLI sign-in). */
83	  chatgpt: {
84	    id: "chatgpt",
85	    label: "ChatGPT plan",
86	    protocol: "openai-responses",
87	    baseUrl: "https://chatgpt.com/backend-api/codex",
88	    auth: "oauth",
89	    staticHeaders: { originator: "nexus" },
90	    usage: "native",
91	    streamOnly: true,
92	    // The Codex backend serves reasoning models only and sets its own output limit.
93	    omitParams: ["temperature", "max_output_tokens"],
94	    methods: [{ id: "chatgpt-oauth", label: "Sign in with ChatGPT (unofficial)", kind: "browser", unofficial: true }],
95	  },
96	  /** GitHub Copilot subscription (unofficial: VS Code Copilot sign-in). */
97	  copilot: {
98	    id: "copilot",
99	    label: "GitHub Copilot",
100	    protocol: "openai-chat",
101	    baseUrl: "https://api.githubcopilot.com",
102	    auth: "oauth",
103	    usage: "native",
104	    methods: [{ id: "copilot-device", label: "Sign in with GitHub (unofficial)", kind: "device", unofficial: true }],
105	  },
106	  /** Any other OpenAI-compatible Chat Completions service; its base URL must be configured by the operator. */
107	  compatible: {
108	    id: "compatible",
109	    label: "OpenAI-compatible",
110	    protocol: "openai-chat",
111	    credentialEnv: "NEXUS_COMPATIBLE_API_KEY",
112	    auth: "bearer",
113	    usage: "stream-options",
114	    methods: [{ id: "api-key", label: "API key", kind: "key" }],
115	  },
116	});
117	
118	export function providerDefinition(id: string | undefined): ProviderDefinition | undefined {
119	  return id ? PROVIDERS[id] : undefined;
120	}
121	
122	/** `NEXUS_<ID>_BASE_URL`: the operator's override of a provider's base URL. */
123	export function baseUrlSetting(id: string): string {
124	  return `NEXUS_${id.toUpperCase()}_BASE_URL`;
125	}
126	
127	export function originOf(url: string | undefined): string | undefined {
128	  if (!url?.trim()) return undefined;
129	  try {
130	    return new URL(url.trim()).origin;
131	  } catch {
132	    return undefined;
133	  }
134	}
135	
136	export interface ResolvedConnection {
137	  /** Undefined for the legacy appliance/endpoint path. */
138	  providerId?: string;
139	  label: string;
140	  protocol: WireProtocol;
141	  auth: AuthStyle;
142	  staticHeaders: Record<string, string>;
143	  usage: ProviderDefinition["usage"] | "none";
144	  /** Whether requests carry the appliance's X-Task-Class routing hint. */
145	  sendTaskClass: boolean;
146	  streamOnly: boolean;
147	  omitParams: string[];
148	}
149	
150	/** Copilot serves some models through the Responses API only. */
151	export function protocolFor(providerId: string | undefined, model: string): WireProtocol | undefined {
152	  if (providerId === "copilot" && /^gpt-5/i.test(model)) return "openai-responses";
153	  return undefined;
154	}
155	
156	export function connectionFor(providerId: string | undefined, model = ""): ResolvedConnection {
157	  const def = providerDefinition(providerId);
158	  if (!def) {
159	    // Usage is requested (OpenAI-compatible servers such as llama.cpp, vLLM and the appliance gateway report it, with
160	    // cached-token counts); a server that rejects stream_options has it dropped and the request retried.
161	    return { label: "endpoint", protocol: "openai-chat", auth: "bearer", staticHeaders: {}, usage: "stream-options", sendTaskClass: true, streamOnly: false, omitParams: [] };
162	  }
163	  return {
164	    providerId: def.id,
165	    label: def.label,
166	    protocol: protocolFor(def.id, model) ?? def.protocol,
167	    auth: def.auth,
168	    staticHeaders: { ...(def.staticHeaders ?? {}) },
169	    usage: def.usage,
170	    sendTaskClass: false,
171	    streamOnly: Boolean(def.streamOnly),
172	    omitParams: [...(def.omitParams ?? [])],
173	  };
174	}
175	
176	/**
177	 * Disclosure class of a destination: "cloud" when content sent there leaves the operator's machines and network.
178	 * URL locality is not sufficient: an origin the operator lists in NEXUS_CLOUD_ROUTED_ORIGINS (a local gateway that
179	 * forwards to a cloud service) is cloud, and every named provider except `compatible` is cloud by definition.
180	 */
181	export function disclosureClass(url: string, providerId: string | undefined, cloudRoutedOrigins: readonly string[] = []): "local" | "cloud" {
182	  if (providerId && providerId !== "compatible") return "cloud";
183	  const origin = originOf(url);
184	  if (origin && cloudRoutedOrigins.includes(origin)) return "cloud";
185	  const boundary = classifyDestination(url);
186	  return boundary === "EXTERNAL_PUBLIC" || boundary === "EXTERNAL_BOUNDED" ? "cloud" : "local";
187	}
188	
189	export function parseOriginList(raw: string | undefined): string[] {
190	  return (raw ?? "").split(",").map((o) => originOf(o)).filter((o): o is string => Boolean(o));
191	}
192	
193	/** The environment variable a provider connection reads its key from (for operator-facing messages). */
194	export function operatorSettingKeyForAuth(id: string): string {
195	  const def = providerDefinition(id);
196	  return def?.credentialEnv ?? (def ? `sign in with /model → ctrl+p → ${def.label}` : "the provider's API key variable");
197	}
